import fs from "fs";

const p = "c:/Tekcroft/lib/franchise-seo-body.html";
let h = fs.readFileSync(p, "utf8");
const start = h.indexOf('<section class="sec wk" id="work">');
const faq = h.indexOf('<section class="sec faq" id="faq">');
if (start < 0 || faq < 0) {
  console.error("markers", start, faq);
  process.exit(1);
}
